import{_ as e,o as a,c as d,a2 as s}from"./chunks/framework.Bg-Zxr5O.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/SPLIT-FILE.md","filePath":"manual-en/SPLIT-FILE.md","lastUpdated":1785684581000}'),i={name:"manual-en/SPLIT-FILE.md"};function r(o,t,n,l,c,p){return a(),d("div",null,[...t[0]||(t[0]=[s(`<h3 id="_13-5-split-file" tabindex="-1">13.5 SPLIT FILE <a class="header-anchor" href="#_13-5-split-file" aria-label="Permalink to &quot;13.5 SPLIT FILE&quot;">​</a></h3><pre><code>SPLIT FILE [{LAYERED, SEPARATE}] BY var_list.
SPLIT FILE OFF.
</code></pre><p><code>SPLIT FILE</code> allows multiple sets of data present in one data file to be analyzed separately using single statistical procedure commands.</p><p>Specify a list of variable names to analyze multiple sets of data separately. Groups of adjacent cases having the same values for these variables are analyzed by statistical procedure commands as one group. An independent analysis is carried out for each group of cases, and the variable values for the group are printed along with the analysis.</p><p>When a list of variable names is specified, one of the keywords <code>LAYERED</code> or <code>SEPARATE</code> may also be specified. With <code>LAYERED</code>, which is the default, the separate analyses for each group are presented together in a single table. With <code>SEPARATE</code>, each analysis is presented in a separate table. Not all procedures honor the distinction.</p><p>Groups are formed only by <em>adjacent</em> cases. To create a split using a variable where like values are not adjacent in the working file, first sort the data by that variable (see <a href="./SORT-CASES">SORT CASES</a>).</p><p>Specify <code>OFF</code> to disable <code>SPLIT FILE</code> and resume analysis of the entire active dataset as a single group of data.</p><p>When <code>SPLIT FILE</code> is specified after <code>TEMPORARY</code>, it affects only the next procedure (see <a href="./TEMPORARY">TEMPORARY</a>).</p><h4 id="_13-5-1-example-split" tabindex="-1">13.5.1 Example Split <a class="header-anchor" href="#_13-5-1-example-split" aria-label="Permalink to &quot;13.5.1 Example Split&quot;">​</a></h4><p>The file horticulture.sav contains data describing the <strong>yield</strong> of a number of horticultural specimens which have been subjected to various <strong>treatment</strong> s. If we wanted to investigate linear statistics of the <strong>yeild</strong> , one way to do this is using the <code>DESCRIPTIVES</code> (see <a href="./DESCRIPTIVES">DESCRIPTIVES</a>). However, it is reasonable to expect the mean to be different depending on the <strong>treatment</strong>. So we might want to perform three separate procedures — one for each treatment. 5 Example 13.2 shows how this can be done automatically using the <code>SPLIT FILE</code> command.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>get file=&#39;horticulture.sav&#39;.  * Ensure cases are sorted before splitting. sort cases by treatment.  split file by treatment.  * Run descriptives on the yield variable descriptives /variable = yield.</span></span></code></pre></div><p><strong>Example 13.2:</strong> Running <code>DESCRIPTIVES</code> on each value of <strong>treatment</strong></p><p>In Example 13.3 you can see that the table of descriptive statistics appears 3 times — once for each value of <strong>treatment</strong>. In this example ‘N’, the number of observations are identical in all splits. This is because that experiment was deliberately designed that way. However in general one can expect a different ‘N’ for each split.</p><table tabindex="0"><thead><tr><th></th><th>N</th><th>Mean</th><th>Std Dev</th><th>Minimum</th><th>Maximum</th></tr></thead><tbody><tr><td>Variable</td><td>Value</td><td></td><td></td><td></td><td></td></tr><tr><td>treatment</td><td>control</td><td></td><td></td><td></td><td></td></tr><tr><td>yield</td><td>30</td><td>51.23</td><td>8.28</td><td>37.86</td><td>68.59</td></tr><tr><td>Valid N (listwise)</td><td>30</td><td></td><td></td><td></td><td></td></tr><tr><td>Missing N (listwise)</td><td>0</td><td></td><td></td><td></td><td></td></tr><tr><td>Variable</td><td>Value</td><td></td><td></td><td></td><td></td></tr><tr><td>treatment</td><td>conventional</td><td></td><td></td><td></td><td></td></tr><tr><td></td><td>N</td><td>Mean</td><td>Std Dev</td><td>Minimum</td><td>Maximum</td></tr><tr><td>yield</td><td>30</td><td>53.57</td><td>8.92</td><td>36.30</td><td>70.66</td></tr><tr><td>Valid N (listwise)</td><td>30</td><td></td><td></td><td></td><td></td></tr><tr><td>Missing N (listwise)</td><td>0</td><td></td><td></td><td></td><td></td></tr><tr><td>Variable</td><td>Value</td><td></td><td></td><td></td><td></td></tr><tr><td>treatment</td><td>traditional</td><td></td><td></td><td></td><td></td></tr><tr><td></td><td>N</td><td>Mean</td><td>Std Dev</td><td>Minimum</td><td>Maximum</td></tr><tr><td>yield</td><td>30</td><td>56.87</td><td>8.88</td><td>39.08</td><td>75.93</td></tr><tr><td>Valid N (listwise)</td><td>30</td><td></td><td></td><td></td><td></td></tr><tr><td>Missing N (listwise)</td><td>0</td><td></td><td></td><td></td><td></td></tr></tbody></table><p><strong>Example 13.3:</strong> The results of running <code>DESCRIPTIVES</code> with an active split</p><p>Unless <code>TEMPORARY</code> was used, after a split has been defined for a dataset it remains active until explicitly disabled. In the graphical user interface, the active split variable (if any) is displayed in the status bar (see Screenshot 13.1. If a dataset is saved to a system file (see <a href="./SAVE">SAVE</a>) whilst a split is active, the split stastus is stored in the file and will be automatically loaded when that file is loaded.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span></code></pre></div><p><strong>Screenshot 13.1:</strong> The status bar indicating that the data set is split using the <strong>treatment</strong> variable</p><h4 id="footnotes" tabindex="-1">Footnotes <a class="header-anchor" href="#footnotes" aria-label="Permalink to &quot;Footnotes&quot;">​</a></h4><h5 id="_5" tabindex="-1">(5) <a class="header-anchor" href="#_5" aria-label="Permalink to &quot;(5)&quot;">​</a></h5><p>There are other, possibly better, ways to achieve a similar result using the <code>MEANS</code> or <code>EXAMINE</code> commands.</p>`,21)])])}const m=e(i,[["render",r]]);export{u as __pageData,m as default};
